const state={products:load('products',PRODUCT_SEED),orders:load('orders',ORDER_SEED),cart:load('cart',[]),wishlist:load('wishlist',[]),category:'Всички',search:'',adminTab:'dashboard',accountTab:'orders'};
function load(k,f){try{return JSON.parse(localStorage.getItem('ch_'+k))||f}catch{return f}}
function save(k,v){localStorage.setItem('ch_'+k,JSON.stringify(v))}
const money=n=>`${Number(n).toFixed(2)} лв.`;
const qs=s=>document.querySelector(s);const qsa=s=>[...document.querySelectorAll(s)];
function toast(msg){let t=qs('.toast'); if(!t){t=document.createElement('div');t.className='toast';document.body.appendChild(t)} t.textContent=msg;t.classList.add('on');setTimeout(()=>t.classList.remove('on'),1800)}
function header(){return `<div class="announcement">🚚 Безплатна доставка за поръчки над 100 лв. · 14 дни право на връщане</div><header class="header"><div class="shell"><div class="header-main"><a class="brand" href="#home"><img src="assets/logo.png" alt="Чаршафчето"></a><div class="search-wrap"><input id="globalSearch" class="search" placeholder="Търси спални комплекти, чаршафи, калъфки…" value="${esc(state.search)}"><button class="search-btn" data-search>⌕</button></div><div class="header-actions"><button class="icon-btn" data-route="account" title="Моят профил">👤</button><button class="icon-btn" data-wishlist title="Любими">♡<span class="badge">${state.wishlist.length}</span></button><button class="icon-btn" data-cart title="Количка">🛒<span class="badge">${cartCount()}</span></button><button class="icon-btn mobile-menu" data-route="shop">☰</button></div></div><nav class="nav"><a href="#home">Начало</a><a href="#shop" data-cat="Спални комплекти">Спални комплекти</a><a href="#shop" data-cat="Чаршафи">Чаршафи</a><a href="#shop" data-cat="Калъфки">Калъфки</a><a href="#shop" data-cat="Завивки">Олекотени завивки</a><a href="#shop">Всички продукти</a><a href="#shop" class="accent">Промоции</a><span class="nav-spacer"></span><a href="#admin" class="admin-link">Админ портал</a></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="shell footer-grid"><div><img class="footer-logo" src="assets/logo.png" alt="Чаршафчето"><p>Повече уют в живота. Български дух, съвременен комфорт.</p></div><div><h4>Полезни връзки</h4><a href="#home">Начало</a><a href="#shop">Всички продукти</a><a href="#shop">Промоции</a><a href="#account">Моят профил</a></div><div><h4>Обслужване</h4><a href="#">Доставка</a><a href="#">Връщане и рекламации</a><a href="#">Общи условия</a><a href="#">Политика за поверителност</a></div><div><h4>Свържете се с нас</h4><p>☎ 0888 123 456</p><p>✉ info@charshafcheto.bg</p><p>📍 България</p></div></div><div class="shell copyright">© 2026 Чаршафчето. Всички права запазени.</div></footer>`}
function home(){return `${header()}<main><section class="hero"><div class="shell hero-grid"><div class="hero-copy"><div class="eyebrow">Текстил с български дух</div><h1>Комфорт и стил <span class="accent">за всяка спалня</span></h1><p>Качествени спални комплекти, чаршафи и текстил за дома, вдъхновени от българските традиции и създадени за вашия уют.</p><div class="hero-cta"><a class="btn btn-primary" href="#shop">Разгледай колекцията →</a><button class="btn btn-secondary" data-route="account">Моят профил</button></div><div class="trust-row"><span>✓ Качествени материи</span><span>✓ Бърза доставка</span><span>✓ Лесно връщане</span></div></div><div class="hero-art"><img src="assets/products/hero.svg" alt="Спалня Чаршафчето"><div class="hero-note">Повече уют<br>в живота! ♥</div></div></div></section>
<section class="section"><div class="shell"><div class="section-head"><div><div class="folkline"><span class="folkmark"><i>◆</i> ✦ <i>◆</i></span><h2 class="section-title">Нашите <span class="accent">категории</span></h2></div><p class="section-sub">Всичко необходимо за една по-уютна спалня.</p></div><a href="#shop" class="text-link">Виж всички →</a></div><div class="categories">${categoryCard('Спални комплекти','Стил и уют в хармония','assets/products/zornitsa.svg')}${categoryCard('Чаршафи','За спокоен и качествен сън','assets/products/sheet.svg')}${categoryCard('Калъфки','Малки детайли, голяма разлика','assets/products/pillows.svg')}${categoryCard('Завивки','Топлина през всички сезони','assets/products/duvet.svg')}</div></div></section>
<section class="section tight"><div class="shell"><div class="section-head"><div><div class="folkline"><span class="folkmark"><i>◆</i> ✦ <i>◆</i></span><h2 class="section-title">Популярни <span class="accent">продукти</span></h2></div></div><a href="#shop" class="text-link">Виж всички продукти →</a></div><div class="products">${state.products.slice(0,4).map(productCard).join('')}</div></div></section>
<section class="section tight"><div class="shell"><div class="promo"><div><h3>🚚 Безплатна доставка</h3><p>при поръчки над 100 лв.</p></div><div class="promo-divider"></div><div><h3>🏷️ До 30% отстъпка</h3><p>на избрани спални комплекти</p></div></div></div></section>
<section class="section tight"><div class="shell"><div class="benefits"><div class="benefit"><div class="ico">🌿</div><strong>Качествени материи</strong><span>Подбрани меки тъкани</span></div><div class="benefit"><div class="ico">🚚</div><strong>Бърза доставка</strong><span>До всяка точка в България</span></div><div class="benefit"><div class="ico">📦</div><strong>Лесно връщане</strong><span>До 14 дни</span></div><div class="benefit"><div class="ico">🛡️</div><strong>Сигурно пазаруване</strong><span>Защитени лични данни</span></div></div></div></section>
<section class="section"><div class="shell"><div class="section-head"><div><div class="folkline"><span class="folkmark"><i>◆</i> ✦ <i>◆</i></span><h2 class="section-title">Какво казват нашите <span class="accent">клиенти</span></h2></div></div></div><div class="testimonials"><div class="quote"><div class="stars">★★★★★</div><p>„Страхотно качество и много красиви дизайни. Спалното бельо е меко и уютно.“</p><strong>Мария Петрова</strong></div><div class="quote"><div class="stars">★★★★★</div><p>„Бърза доставка, отлично обслужване и наистина качествени продукти.“</p><strong>Иван Димитров</strong></div><div class="quote"><div class="stars">★★★★★</div><p>„Чаршафчето превърна спалнята ни в истински уютен рай.“</p><strong>Елена Георгиева</strong></div></div></div></section></main>${footer()}${overlays()}`}
function categoryCard(name,sub,img){return `<article class="cat-card" data-catgo="${name}"><div class="cat-visual"><img src="${img}" alt="${name}"></div><div class="cat-info"><div><h3>${name}</h3><p>${sub}</p></div><button class="circle-arrow">→</button></div></article>`}
function productCard(p){const wished=state.wishlist.includes(p.id);return `<article class="product-card">${p.tag?`<span class="tag">${p.tag}</span>`:''}<div class="product-img" data-product="${p.id}"><img src="${p.image}" alt="${esc(p.name)}"></div><div class="product-body"><div class="product-name" data-product="${p.id}">${p.name}</div><div class="product-meta"><span class="stars">★★★★★ <span style="color:#8f887f">(${p.reviews})</span></span><span class="stock">${p.stock>0?'В наличност':'Изчерпан'}</span></div><div class="price-row"><span class="price">${money(p.price)}</span>${p.oldPrice?`<span class="old-price">${money(p.oldPrice)}</span>`:''}</div><div class="card-actions"><button class="btn btn-primary btn-small" data-add="${p.id}" ${p.stock<=0?'disabled':''}>🛒 Добави</button><button class="wish ${wished?'on':''}" data-wish="${p.id}">${wished?'♥':'♡'}</button></div></div></article>`}
function shop(){let items=state.products.filter(p=>(state.category==='Всички'||p.category===state.category)&&(!state.search||p.name.toLowerCase().includes(state.search.toLowerCase())||p.category.toLowerCase().includes(state.search.toLowerCase())));return `${header()}<main class="page"><section class="page-hero"><div class="shell"><div class="crumb">Начало / Магазин</div><h1>Магазин</h1><p class="section-sub">Открийте колекцията на Чаршафчето.</p></div></section><section class="section"><div class="shell"><div class="toolbar">${['Всички','Спални комплекти','Чаршафи','Калъфки','Завивки'].map(c=>`<button class="chip ${state.category===c?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div>${items.length?`<div class="products">${items.map(productCard).join('')}</div>`:`<div class="empty panel">Няма продукти, които отговарят на търсенето.</div>`}</div></section></main>${footer()}${overlays()}`}
function productPage(id){const p=state.products.find(x=>x.id===id)||state.products[0];return `${header()}<main class="page"><section class="page-hero"><div class="shell"><div class="crumb">Начало / ${p.category} / ${p.name}</div></div></section><section class="section"><div class="shell product-detail"><div class="detail-img"><img src="${p.image}" alt="${p.name}"></div><div class="detail-copy"><div class="eyebrow">${p.category}</div><h2>${p.name}</h2><div class="stars">★★★★★ <span style="color:#716b63">${p.rating} · ${p.reviews} отзива</span></div><div class="price-row"><span class="price">${money(p.price)}</span>${p.oldPrice?`<span class="old-price">${money(p.oldPrice)}</span>`:''}</div><p>${p.desc}</p><div class="form-grid" style="margin:20px 0"><div class="field"><label>Размер</label><select><option>${p.size}</option><option>150 × 220 см</option></select></div><div class="field"><label>Количество</label><select><option>1</option><option>2</option><option>3</option></select></div></div><button class="btn btn-primary" data-add="${p.id}" style="width:100%;font-size:16px">🛒 Добави в количката</button><div class="specs"><div class="spec"><span>Материя</span><strong>${p.material}</strong></div><div class="spec"><span>Комплект</span><strong>${p.pieces}</strong></div><div class="spec"><span>Цвят</span><strong>${p.color}</strong></div><div class="spec"><span>Наличност</span><strong>${p.stock} бр.</strong></div></div></div></div></section></main>${footer()}${overlays()}`}
function account(){return `${header()}<main class="page"><section class="page-hero"><div class="shell"><div class="crumb">Начало / Моят профил</div><h1>Моят профил</h1></div></section><section class="section"><div class="shell account-layout"><aside class="side">${[['orders','Моите поръчки'],['wishlist','Любими'],['profile','Лични данни'],['addresses','Адреси']].map(([id,l])=>`<button data-accounttab="${id}" class="${state.accountTab===id?'active':''}">${l}</button>`).join('')}</aside><div>${accountPanel()}</div></div></section></main>${footer()}${overlays()}`}
function accountPanel(){if(state.accountTab==='wishlist'){const ps=state.products.filter(p=>state.wishlist.includes(p.id));return `<div class="panel"><h2>Любими продукти</h2>${ps.length?`<div class="products" style="grid-template-columns:repeat(2,1fr)">${ps.map(productCard).join('')}</div>`:'<div class="empty">Все още нямате любими продукти.</div>'}</div>`}if(state.accountTab==='profile')return `<div class="panel"><h2>Лични данни</h2><div class="form-grid"><div class="field"><label>Име</label><input value="Иван Иванов"></div><div class="field"><label>Телефон</label><input value="0888 123 456"></div><div class="field full"><label>Имейл</label><input value="ivan@example.com"></div><div class="field full"><button class="btn btn-primary" onclick="toast('Промените са записани')">Запази промените</button></div></div></div>`;if(state.accountTab==='addresses')return `<div class="panel"><div class="admin-top"><h2>Адреси</h2><button class="btn btn-primary btn-small" onclick="toast('Демо: форма за нов адрес')">+ Добави адрес</button></div><div class="quote"><strong>Основен адрес</strong><p>гр. София, бул. България 100<br>Иван Иванов · 0888 123 456</p></div></div>`;return `<div class="panel"><h2>Моите поръчки</h2><div class="table-wrap"><table class="table"><thead><tr><th>Поръчка</th><th>Дата</th><th>Продукти</th><th>Статус</th><th>Общо</th></tr></thead><tbody><tr><td><b>CH-1058</b></td><td>17.10.2026</td><td>3</td><td>${statusPill('processing')}</td><td><b>175.79 лв.</b></td></tr><tr><td><b>CH-1033</b></td><td>01.10.2026</td><td>1</td><td>${statusPill('delivered')}</td><td><b>69.90 лв.</b></td></tr></tbody></table></div></div>`}
function admin(){return `${header()}<main class="page"><section class="page-hero"><div class="shell"><div class="crumb">Чаршафчето / Администрация</div><h1>Админ портал</h1><p class="section-sub">Демо среда — данните се пазят локално в браузъра.</p></div></section><section class="section"><div class="shell admin-layout"><aside class="side">${[['dashboard','Табло'],['products','Продукти'],['orders','Поръчки'],['clients','Клиенти'],['discounts','Отстъпки'],['settings','Настройки']].map(([id,l])=>`<button data-admintab="${id}" class="${state.adminTab===id?'active':''}">${l}</button>`).join('')}</aside><div>${adminPanel()}</div></div></section></main>${footer()}${overlays()}`}
function adminPanel(){if(state.adminTab==='products')return productsAdmin();if(state.adminTab==='orders')return ordersAdmin();if(state.adminTab==='clients')return clientsAdmin();if(state.adminTab==='discounts')return `<div class="panel"><div class="admin-top"><h2>Отстъпки и промо кодове</h2><button class="btn btn-primary btn-small" onclick="toast('Демо: нов промо код')">+ Нов код</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Код</th><th>Отстъпка</th><th>Условие</th><th>Статус</th></tr></thead><tbody><tr><td><b>WELCOME10</b></td><td>10%</td><td>Първа поръчка</td><td><span class="status delivered">Активен</span></td></tr><tr><td><b>FREEDELIVERY</b></td><td>Доставка</td><td>Над 100 лв.</td><td><span class="status delivered">Активен</span></td></tr></tbody></table></div></div>`;if(state.adminTab==='settings')return `<div class="panel"><h2>Настройки на магазина</h2><div class="form-grid"><div class="field"><label>Име на магазина</label><input value="Чаршафчето"></div><div class="field"><label>Валута</label><select><option>BGN (лв.)</option><option>EUR (€)</option></select></div><div class="field"><label>Безплатна доставка над</label><input value="100"></div><div class="field"><label>Имейл за поръчки</label><input value="orders@charshafcheto.bg"></div><div class="field full"><button class="btn btn-primary" onclick="toast('Настройките са записани')">Запази</button></div></div></div>`;return dashboardAdmin()}
function dashboardAdmin(){const revenue=state.orders.reduce((s,o)=>s+o.total,0);const low=state.products.filter(p=>p.stock<10).length;return `<div class="kpis"><div class="kpi"><small>Оборот</small><b>${money(revenue)}</b><em>↑ демо период</em></div><div class="kpi"><small>Поръчки</small><b>${state.orders.length}</b><em>${state.orders.filter(o=>o.status==='new').length} нови</em></div><div class="kpi"><small>Продукти</small><b>${state.products.length}</b><em>${low} с ниска наличност</em></div><div class="kpi"><small>Клиенти</small><b>${uniqueClients().length}</b><em>активни профили</em></div></div><div class="panel"><div class="admin-top"><h2>Последни поръчки</h2><button class="btn btn-secondary btn-small" data-admintab="orders">Всички поръчки</button></div>${ordersTable(state.orders.slice(0,5))}</div>`}
function productsAdmin(){return `<div class="panel"><div class="admin-top"><h2>Продукти</h2><button class="btn btn-primary btn-small" data-newproduct>+ Добави продукт</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Продукт</th><th>Категория</th><th>Цена</th><th>Наличност</th><th></th></tr></thead><tbody>${state.products.map(p=>`<tr><td><b>${p.name}</b></td><td>${p.category}</td><td>${money(p.price)}</td><td>${p.stock} бр.</td><td><div class="mini-actions"><button data-edit="${p.id}">Редактирай</button><button class="danger" data-delete="${p.id}">Изтрий</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function ordersAdmin(){return `<div class="panel"><div class="admin-top"><h2>Поръчки</h2><button class="btn btn-secondary btn-small" onclick="toast('CSV export е готов за реалната версия')">Експорт</button></div>${ordersTable(state.orders,true)}</div>`}
function ordersTable(orders,editable=false){return `<div class="table-wrap"><table class="table"><thead><tr><th>Поръчка</th><th>Клиент</th><th>Дата</th><th>Статус</th><th>Общо</th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>${o.id}</b></td><td>${o.client}<br><span style="color:#8c857c">${o.phone}</span></td><td>${o.date}</td><td>${editable?`<select data-orderstatus="${o.id}" style="padding:7px;border:1px solid #e8dfd2;border-radius:8px"><option value="new" ${o.status==='new'?'selected':''}>Нова</option><option value="processing" ${o.status==='processing'?'selected':''}>Обработва се</option><option value="shipped" ${o.status==='shipped'?'selected':''}>Изпратена</option><option value="delivered" ${o.status==='delivered'?'selected':''}>Доставена</option><option value="cancelled" ${o.status==='cancelled'?'selected':''}>Отказана</option></select>`:statusPill(o.status)}</td><td><b>${money(o.total)}</b></td></tr>`).join('')}</tbody></table></div>`}
function clientsAdmin(){return `<div class="panel"><h2>Клиенти</h2><div class="table-wrap"><table class="table"><thead><tr><th>Клиент</th><th>Имейл</th><th>Телефон</th><th>Поръчки</th><th>Оборот</th></tr></thead><tbody>${uniqueClients().map(c=>`<tr><td><b>${c.client}</b></td><td>${c.email}</td><td>${c.phone}</td><td>${c.orders}</td><td><b>${money(c.total)}</b></td></tr>`).join('')}</tbody></table></div></div>`}
function uniqueClients(){const map={};state.orders.forEach(o=>{if(!map[o.email])map[o.email]={client:o.client,email:o.email,phone:o.phone,orders:0,total:0};map[o.email].orders++;map[o.email].total+=o.total});return Object.values(map)}
function statusPill(s){const labels={new:'Нова',processing:'Обработва се',shipped:'Изпратена',delivered:'Доставена',cancelled:'Отказана'};return `<span class="status ${s}">${labels[s]||s}</span>`}
function overlays(){return `<div class="overlay"></div><aside class="drawer" id="cartDrawer"><div class="drawer-head"><h2>Вашата количка</h2><button class="close" data-close>×</button></div><div class="drawer-content" id="cartContent"></div><div class="drawer-footer" id="cartFooter"></div></aside><div class="modal" id="checkoutModal"><div class="modal-box"><div class="modal-head"><h2>Завършване на поръчката</h2><button class="close" data-closemodal>×</button></div><div class="modal-body"><form id="checkoutForm"><div class="form-grid"><div class="field"><label>Име и фамилия</label><input name="name" required></div><div class="field"><label>Телефон</label><input name="phone" required></div><div class="field full"><label>Имейл</label><input name="email" type="email" required></div><div class="field"><label>Доставка</label><select name="delivery"><option>Speedy — офис</option><option>Econt — офис</option><option>До адрес</option></select></div><div class="field"><label>Плащане</label><select name="payment"><option>Наложен платеж</option><option>Карта (демо)</option><option>Банков превод</option></select></div><div class="field full"><label>Адрес / офис на куриер</label><input name="address" required></div><div class="field full"><button class="btn btn-primary" style="width:100%">Потвърди поръчката</button></div></div></form></div></div></div><div class="modal" id="productModal"><div class="modal-box"><div class="modal-head"><h2 id="productModalTitle">Продукт</h2><button class="close" data-closemodal>×</button></div><div class="modal-body" id="productModalBody"></div></div></div>`}
function cartCount(){return state.cart.reduce((s,x)=>s+x.qty,0)}
function cartItems(){return state.cart.map(ci=>({...ci,product:state.products.find(p=>p.id===ci.id)})).filter(x=>x.product)}
function cartTotal(){return cartItems().reduce((s,x)=>s+x.product.price*x.qty,0)}
function openCart(){renderCart();qs('.overlay').classList.add('on');qs('#cartDrawer').classList.add('on')}
function closeOverlays(){qs('.overlay')?.classList.remove('on');qs('#cartDrawer')?.classList.remove('on');qsa('.modal.on').forEach(m=>m.classList.remove('on'))}
function renderCart(){const c=qs('#cartContent'),f=qs('#cartFooter');if(!c)return;const items=cartItems();c.innerHTML=items.length?items.map(({id,qty,product:p})=>`<div class="cart-item"><img src="${p.image}" alt="${p.name}"><div><b>${p.name}</b><div style="color:#6d6a64;font-size:12px;margin-top:3px">${money(p.price)}</div><div class="qty"><button data-qty="${id}" data-delta="-1">−</button><span>${qty}</span><button data-qty="${id}" data-delta="1">+</button></div></div><button class="close" style="width:30px;height:30px;font-size:16px" data-remove="${id}">×</button></div>`).join(''):'<div class="empty">Количката е празна.<br><br><a href="#shop" class="btn btn-primary" data-close>Към магазина</a></div>';f.innerHTML=items.length?`<div class="cart-total"><span>Общо</span><span>${money(cartTotal())}</span></div><button class="btn btn-primary" style="width:100%" data-checkout>Към поръчка →</button>`:''}
function addCart(id){const p=state.products.find(x=>x.id===id);if(!p||p.stock<=0)return;const x=state.cart.find(x=>x.id===id);if(x)x.qty++;else state.cart.push({id,qty:1});save('cart',state.cart);rerenderBadges();toast('Добавено в количката')}
function toggleWish(id){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];save('wishlist',state.wishlist);render()}
function rerenderBadges(){qsa('[data-cart] .badge').forEach(x=>x.textContent=cartCount());qsa('[data-wishlist] .badge').forEach(x=>x.textContent=state.wishlist.length)}
function openProductAdmin(id){const p=id?state.products.find(x=>x.id===id):{id:'p'+Date.now(),name:'',category:'Спални комплекти',price:0,stock:0,image:'assets/products/zornitsa.svg',material:'100% памук',size:'200 × 230 см',pieces:'6 части',color:'',desc:'',rating:5,reviews:0,tag:null,oldPrice:null};qs('#productModalTitle').textContent=id?'Редактиране на продукт':'Нов продукт';qs('#productModalBody').innerHTML=`<form id="productForm" data-id="${p.id}"><div class="form-grid"><div class="field full"><label>Име</label><input name="name" value="${esc(p.name)}" required></div><div class="field"><label>Категория</label><select name="category">${['Спални комплекти','Чаршафи','Калъфки','Завивки'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Цена</label><input name="price" type="number" step="0.01" value="${p.price}" required></div><div class="field"><label>Наличност</label><input name="stock" type="number" value="${p.stock}" required></div><div class="field"><label>Материя</label><input name="material" value="${esc(p.material)}"></div><div class="field"><label>Размер</label><input name="size" value="${esc(p.size)}"></div><div class="field"><label>Цвят</label><input name="color" value="${esc(p.color)}"></div><div class="field"><label>Изображение</label><select name="image">${state.products.map(x=>`<option value="${x.image}" ${p.image===x.image?'selected':''}>${x.image.split('/').pop()}</option>`).join('')}</select></div><div class="field full"><label>Описание</label><textarea name="desc">${esc(p.desc)}</textarea></div><div class="field full"><button class="btn btn-primary">Запази продукта</button></div></div></form>`;qs('#productModal').classList.add('on')}
function esc(s=''){return String(s).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function route(){const hash=location.hash.slice(1)||'home';if(hash.startsWith('product/'))return {name:'product',id:hash.split('/')[1]};return {name:hash}}
function render(){const r=route();let html;if(r.name==='shop')html=shop();else if(r.name==='product')html=productPage(r.id);else if(r.name==='admin')html=admin();else if(r.name==='account')html=account();else html=home();qs('#app').innerHTML=html;bind();window.scrollTo({top:0,behavior:'instant'})}
function bind(){qs('#globalSearch')?.addEventListener('keydown',e=>{if(e.key==='Enter'){state.search=e.target.value.trim();state.category='Всички';location.hash='shop'}});qs('[data-search]')?.addEventListener('click',()=>{state.search=qs('#globalSearch').value.trim();state.category='Всички';location.hash='shop'});qsa('[data-route]').forEach(b=>b.onclick=()=>location.hash=b.dataset.route);qsa('[data-cat]').forEach(a=>a.onclick=()=>{state.category=a.dataset.cat;state.search=''});qsa('[data-catgo]').forEach(x=>x.onclick=()=>{state.category=x.dataset.catgo;state.search='';location.hash='shop'});qsa('[data-filter]').forEach(b=>b.onclick=()=>{state.category=b.dataset.filter;render()});qsa('[data-product]').forEach(x=>x.onclick=()=>location.hash='product/'+x.dataset.product);qsa('[data-add]').forEach(b=>b.onclick=e=>{e.stopPropagation();addCart(b.dataset.add)});qsa('[data-wish]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleWish(b.dataset.wish)});qsa('[data-cart]').forEach(b=>b.onclick=openCart);qsa('[data-close]').forEach(b=>b.onclick=closeOverlays);qs('.overlay')?.addEventListener('click',closeOverlays);qsa('[data-closemodal]').forEach(b=>b.onclick=closeOverlays);qsa('[data-accounttab]').forEach(b=>b.onclick=()=>{state.accountTab=b.dataset.accounttab;render()});qsa('[data-admintab]').forEach(b=>b.onclick=()=>{state.adminTab=b.dataset.admintab;render()});qsa('[data-newproduct]').forEach(b=>b.onclick=()=>openProductAdmin());qsa('[data-edit]').forEach(b=>b.onclick=()=>openProductAdmin(b.dataset.edit));qsa('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Да изтрия ли продукта?')){state.products=state.products.filter(p=>p.id!==b.dataset.delete);save('products',state.products);render()}});qsa('[data-orderstatus]').forEach(s=>s.onchange=()=>{const o=state.orders.find(x=>x.id===s.dataset.orderstatus);if(o){o.status=s.value;save('orders',state.orders);toast('Статусът е обновен')}});document.addEventListener('click',delegatedClick,{once:true});qs('#checkoutForm')?.addEventListener('submit',checkoutSubmit);qs('#productForm')?.addEventListener('submit',productSubmit)}
function delegatedClick(e){const q=e.target.closest('[data-qty]'),rm=e.target.closest('[data-remove]'),co=e.target.closest('[data-checkout]');if(q){const x=state.cart.find(x=>x.id===q.dataset.qty);if(x){x.qty=Math.max(1,x.qty+Number(q.dataset.delta));save('cart',state.cart);renderCart();rerenderBadges()}}if(rm){state.cart=state.cart.filter(x=>x.id!==rm.dataset.remove);save('cart',state.cart);renderCart();rerenderBadges()}if(co){closeOverlays();qs('#checkoutModal').classList.add('on')}}
function checkoutSubmit(e){e.preventDefault();const fd=new FormData(e.target),id='CH-'+(1059+state.orders.length);state.orders.unshift({id,client:fd.get('name'),email:fd.get('email'),phone:fd.get('phone'),date:new Date().toLocaleDateString('bg-BG'),total:cartTotal(),status:'new',items:cartCount()});save('orders',state.orders);state.cart=[];save('cart',state.cart);closeOverlays();toast('Поръчката е приета: '+id);setTimeout(()=>{state.accountTab='orders';location.hash='account'},900)}
function productSubmit(e){e.preventDefault();const fd=new FormData(e.target),id=e.target.dataset.id;let p=state.products.find(x=>x.id===id);const isNew=!p;if(isNew){p={id,rating:5,reviews:0,tag:null,oldPrice:null,pieces:'6 части'};state.products.push(p)}['name','category','image','material','size','color','desc'].forEach(k=>p[k]=fd.get(k));p.price=Number(fd.get('price'));p.stock=Number(fd.get('stock'));save('products',state.products);closeOverlays();toast(isNew?'Продуктът е добавен':'Продуктът е обновен');render()}
window.addEventListener('hashchange',render);document.addEventListener('DOMContentLoaded',render);
